// status2 Track A1 (SPEC2 §3.5, §4.2; F1 §3.4.1; ADDENDUM2 §4.2): writes app/lib/battle/ability-table.ts from the pinned
// Showdown c23d2e94 dex (the runnable copy scripts/.cache/calc-audit/showdown, the four mods: gen9 for Scarlet/Violet,
// champions, gen8 for Sword/Shield, gen7 for Ultra Sun/Ultra Moon) and the four catalogs. Per game, per catalog ability with a
// flag or a handler the 2v2 turn's ability changes read: the flags (breakable, cantsuppress, failroleplay, failskillswap,
// noentrain, noreceiver, notrace, notransform) and which of Start, SwitchIn, End and Update it has.
// tests/source/doubles-ability-table.test.ts checks every entry against the pinned dex.
// Run from the repo root:
//   npx --no-install tsx scripts/.cache/calc-audit/status2/build/gen-ability-table.ts > <scratch>/ability-table.ts
//   (then copy it over app/lib/battle/ability-table.ts once it ran clean)
import fs from "node:fs";
import * as sim from "../../showdown/sim/index.ts";

const { Dex } = sim as any;
const GAMES = [
  ["scarlet_violet", "data/battle/scarlet_violet/catalog.json", "gen9"],
  ["champions", "data/champions/catalog.json", "champions"],
  ["sword_shield", "data/battle/sword_shield/catalog.json", "gen8"],
  ["ultra_sun_ultra_moon", "data/battle/ultra_sun_ultra_moon/catalog.json", "gen7"],
] as const;
const FLAGS = ["breakable", "cantsuppress", "failroleplay", "failskillswap", "noentrain", "noreceiver", "notrace", "notransform"];
const HOOKS: [string, string][] = [["onStart", "start"], ["onSwitchIn", "switchIn"], ["onEnd", "end"], ["onUpdate", "update"]];

const lines: string[] = [];
const counts: Record<string, number> = {};
for (const [game, file, mod] of GAMES) {
  const catalog = JSON.parse(fs.readFileSync(file, "utf8"));
  const dex = Dex.mod(mod);
  const rows: string[] = [];
  for (const id of catalog.abilities.map((row: { id: string }) => row.id).sort()) {
    const ability = dex.abilities.get(id);
    if (!ability?.exists) throw new Error(`${game} ${id}: not in the pinned dex`);
    const flags = FLAGS.filter((flag) => ability.flags?.[flag]);
    const hooks = HOOKS.filter(([hook]) => typeof ability[hook] === "function").map(([, key]) => key);
    if (!flags.length && !hooks.length) continue;
    const parts = [`flags:{${flags.map((flag) => `${flag}:true`).join(",")}}`, ...hooks.map((key) => `${key}:true`)];
    rows.push(`    ${id}: {${parts.join(",")}},`);
  }
  counts[game] = rows.length;
  lines.push(`  ${game}: {\n${rows.join("\n")}\n  },`);
}

console.log(`// Generated by scripts/.cache/calc-audit/status2/build/gen-ability-table.ts from pinned Showdown c23d2e94
// (data/abilities.ts with the mods applied: gen 9 for Scarlet/Violet, data/mods/champions, data/mods/gen8, data/mods/gen7).
// Data only, no engine imports: per game, every catalog ability with a flag or a Start, SwitchIn, End or Update handler
// (an ability of the catalog that is not listed has none). The 2v2 turn's ability changes read it (doubles-abilities.ts:
// Skill Swap, Role Play, Entrainment, Simple Beam, Worry Seed, Gastro Acid, Doodle, Transform, Trace; status2 SPEC2 §4.2).
// tests/source/doubles-ability-table.test.ts checks every entry against the pinned dex per game.
import type { BattleGame } from "./types";

/** The ability flags (PS/sim/dex-abilities.ts AbilityFlags). */
export type AbilityFlag = "breakable" | "cantsuppress" | "failroleplay" | "failskillswap" | "noentrain" | "noreceiver" | "notrace" | "notransform";
/**
 * One ability in one game: its flags, and the handlers an ability change runs (PS/sim/pokemon.ts setAbility: the old one's
 * End, the new one's Start; onSwitchIn runs only as it switches in, so an ability gained mid-turn does nothing there; Update
 * at every Update).
 */
export type AbilityEntry = { flags: Partial<Record<AbilityFlag, true>>; start?: true; switchIn?: true; end?: true; update?: true };

export const ABILITY_TABLE: Readonly<Record<BattleGame, Readonly<Record<string, AbilityEntry>>>> = {
${lines.join("\n")}
};

const NONE: AbilityEntry = { flags: {} };
/** The ability's entry in \`game\` (no flag and no handler when it is not listed). */
export function abilityEntry(id: string, game: BattleGame): AbilityEntry {
  return ABILITY_TABLE[game][id] ?? NONE;
}
/** Whether the ability has \`flag\` in \`game\`. */
export function abilityFlag(id: string, game: BattleGame, flag: AbilityFlag): boolean {
  return !!ABILITY_TABLE[game][id]?.flags[flag];
}
`);
console.error(JSON.stringify(counts));
